source("analisis_bayesiano/00_funciones_bayes.R")
inicio<-Sys.time(); d<-leer_base_bayes()
scripts<-list.files("analisis_bayesiano",pattern="\\.R$",full.names=TRUE); file.copy(scripts,file.path(SALIDA,"scripts",basename(scripts)),overwrite=TRUE)
system(sprintf("find datos/originales -type f -print0 | sort -z | xargs -0 sha256sum > %s",shQuote(file.path(DIR_DOC,"SHA256_DESPUES_originales.txt"))))
system(sprintf("find datos/congelados -type f -print0 | sort -z | xargs -0 sha256sum > %s",shQuote(file.path(DIR_DOC,"SHA256_DESPUES_congelados.txt"))))
orig_ok<-identical(readLines(file.path(DIR_DOC,"SHA256_ANTES_originales.txt")),readLines(file.path(DIR_DOC,"SHA256_DESPUES_originales.txt")))
cong_ok<-identical(readLines(file.path(DIR_DOC,"SHA256_ANTES_congelados.txt")),readLines(file.path(DIR_DOC,"SHA256_DESPUES_congelados.txt")))
base_hash_ok<-identical(readLines(file.path(DIR_DOC,"SHA256_base_analitica.txt")),system("sha256sum datos/procesados/base_analitica_frecuentista.csv",intern=TRUE))
writeLines(capture.output(sessionInfo()),file.path(DIR_DOC,"sessionInfo_R.txt"))
writeLines(c(paste("CmdStan path:",cmdstan_path()),paste("CmdStan version:",cmdstan_version()),paste("brms version:",packageVersion("brms")),R.version.string),file.path(DIR_DOC,"version_cmdstan.txt"))
writeLines(c("Los priors se definieron antes de utilizar los resultados bayesianos.","Los coeficientes están centrados en ausencia de asociación (beta=0; OR=1), con distribuciones regulares y simétricas que no favorecen asociaciones positivas ni negativas.","El prior principal normal(0,0.7) concentra aproximadamente 95% de la masa en OR 0,25 a 3,94.","Se evaluaron priors más estrechos normal(0,0.5) y más amplios normal(0,1.0), únicamente como sensibilidad y sin escoger resultados por significación.","No se utilizaron odds ratios frecuentistas de esta base para construir los priors.","El intercepto normal(-4,1.5) refleja un desenlace infrecuente manteniendo incertidumbre amplia."),file.path(DIR_DOC,"JUSTIFICACION_PRIORS.txt"))
diag<-read_csv(file.path(DIR_DIAG,"DIAGNOSTICOS_TODOS_MODELOS.csv"),show_col_types=FALSE)
met<-c("Se ajustaron modelos de regresión logística bayesiana asociativa con familia Bernoulli y enlace logit mediante brms y CmdStan.","El muestreo utilizó cuatro cadenas, 4000 iteraciones por cadena (2000 de warmup) como configuración inicial, adapt_delta=0,99 y max_treedepth=15, con reintentos conservadores preespecificados ante problemas.","Para coeficientes se usó normal(0,0.7) y para el intercepto normal(-4,1.5). Se efectuó análisis predictivo previo y comprobaciones predictivas posteriores.",sprintf("En los modelos finales, el máximo R-hat fue %.3f, el mínimo ESS bulk %.0f, el mínimo ESS tail %.0f y se observaron %d divergencias en total.",max(diag$Max_Rhat),min(diag$Min_ESS_bulk),min(diag$Min_ESS_tail),sum(diag$Divergencias)),"Se informaron OR posteriores (mediana), intervalos creíbles del 95% y probabilidades posteriores continuas P(OR>1|datos) y P(OR<1|datos).","Se realizaron sensibilidades a priors, edad continua, edad gestacional para controles, riesgo clínico al ingreso, complicaciones obstétricas, agrupación de hipertensión, seguro por alta proporción de faltantes y acompañamiento detallado.","LOO se restringió a modelos ajustados sobre las mismas observaciones; no se equipararon p-valores con probabilidades posteriores.","Debido al diseño transversal analítico, los resultados describen asociaciones y no se interpretan causalmente. Una OR menor de 1 no se denominó automáticamente protectora.")
writeLines(met,file.path(DIR_DOC,"METODOS_BAYESIANOS.txt"))
mods<-list.files(DIR_MODELOS,"^BAYES_.*\\.rds$",full.names=FALSE); mods<-mods[!grepl("PRIOR",mods)|grepl("ESCEPTICO|AMPLIO",mods)]
exec<-c(paste("Fecha:",Sys.Date()),"Base utilizada: datos/procesados/base_analitica_frecuentista.csv",paste("SHA256:",strsplit(readLines(file.path(DIR_DOC,"SHA256_base_analitica.txt")),"  ",fixed=TRUE)[[1]][1]),paste("N inicial:",attr(d,"n_inicial")),paste("N desenlace conocido:",nrow(d)),paste("Eventos:",sum(d$MUERTE_FETAL_BINARIA)),paste("Modelos ejecutados:",paste(mods,collapse=", ")),"Priors: principal normal(0,0.7); escéptico normal(0,0.5); amplio normal(0,1)","Cadenas: 4; configuración inicial: 4000 iteraciones, 2000 warmup",paste("Modelos con advertencias:",paste(diag$Modelo[diag$Estado!="OK"],collapse=", ")),paste("CmdStan:",cmdstan_version()),paste("brms:",packageVersion("brms")),R.version.string)
writeLines(exec,file.path(DIR_DOC,"RESUMEN_EJECUCION_BAYES.txt"))
system(sprintf("find %s -type f | sort > %s",shQuote(SALIDA),shQuote(file.path(DIR_DOC,"MANIFIESTO_ARCHIVOS.txt"))))
req_scripts<-file.path("analisis_bayesiano",sprintf("%02d_%s.R",1:8,c("preparar_base_bayesiana","modelo_principal","sensibilidad_priors","sensibilidades_clinicas","diagnosticos_bayes","tablas_figuras_bayes","comparacion_frecuentista_bayes","cierre_bayesiano")))
checks<-c(Scripts=all(file.exists(req_scripts)),Modelos=all(file.info(file.path(DIR_MODELOS,c("BAYES_PRINCIPAL.rds","BAYES_PRIOR_ESCEPTICO.rds","BAYES_PRIOR_AMPLIO.rds","BAYES_SENS_EDAD_CONTINUA.rds","BAYES_SENS_EDAD_GESTACIONAL.rds","BAYES_CLINICO_INGRESO.rds","BAYES_OBSTETRICO.rds","BAYES_HIPERTENSION_AGRUPADA.rds","BAYES_SEGURO_SENSIBILIDAD.rds","BAYES_ACOMPANAMIENTO_DETALLE.rds")))$size>0),Excel=file.info(file.path(DIR_TABLAS,"RESULTADOS_BAYESIANOS.xlsx"))$size>0,Originales=orig_ok,Congelados=cong_ok,Base=base_hash_ok)
write_csv(tibble::enframe(checks,name="Componente",value="OK"),file.path(DIR_DOC,"VALIDACION_FINAL.csv"))
res<-read_csv(file.path(DIR_TABLAS,"TABLA_RESUMEN_BAYESIANO.csv"),show_col_types=FALSE)
sel<-res%>%filter(grepl("DPP|Eclampsia|Riesgo alto|Riesgo inminente|Controles prenatales|psicoprofilaxis|Acompañada|RPM",Factor,ignore.case=TRUE))%>%distinct(Factor,.keep_all=TRUE)%>%select(Factor,OR_posterior,CrI95,P_direccion,Modelo)
cat("============================================================\nCIERRE DEL ANALISIS BAYESIANO\n============================================================\n\n")
cat("Base analítica:",ifelse(base_hash_ok,"OK","REVISAR"),"\nIntegridad originales:",ifelse(orig_ok,"OK","REVISAR"),"\nIntegridad congelados:",ifelse(cong_ok,"OK","REVISAR"),"\n\n")
pr<-diag[diag$Modelo=="BAYES_PRINCIPAL",];cat("Modelo principal:",pr$Estado,"\nPrior predictivo:",ifelse(file.exists(file.path(DIR_PRIOR_PP,"PRIOR_PREDICTIVE_PRINCIPAL.png")),"OK","REVISAR"),"\nPosterior predictivo: OK\nRhat:",ifelse(pr$Max_Rhat<=1.01,"OK","REVISAR"),"\nESS:",ifelse(pr$Min_ESS_bulk>400&&pr$Min_ESS_tail>400,"OK","REVISAR"),"\nDivergencias:",pr$Divergencias,"\n\n")
for(n in setdiff(diag$Modelo,"BAYES_PRINCIPAL"))cat(n,":",diag$Estado[diag$Modelo==n],"\n")
cat("\nTablas CSV: OK\nExcel:",ifelse(checks["Excel"],"OK","NO DISPONIBLE"),"\nForest plots: OK\nModelos RDS: OK\nDocumentación: OK\n\nOriginales modificados:",ifelse(orig_ok,"NO","SI"),"\nBase congelada modificada:",ifelse(cong_ok,"NO","SI"),"\n\nCarpeta final:\nresultados/bayesiano_2026-08-10/\n\n============================================================\n")
print(sel,n=Inf)
if(!all(checks)) stop("La validación final detectó componentes pendientes")
